    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A set of items for one person to consume.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "bowl"],
        "required_properties": ["holds liquid", "holds food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller"],
        "required_properties": ["transmits signals"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "A flat area to hold items.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "desk", "side table"],
        "required_properties": ["flat top"]
      },
