        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["chair", "sofa", "armchair"],
        "required_properties": ["supports sitting"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Screen to display content.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screen", "monitor"],
        "required_properties": ["displays video"]
      }
    ],
    "functional_relations": [
