      ,
      "required": true
      },
      {
        "id": "surface_near_seat",
        "relation": "is_near",
        "participant_roles": ["surface", "person_seating"]
      ,
      "required": true
      },
      {
        "id": "control_accessible",
        "relation": "is_accessible_to",
        "participant_roles": ["entertainment_control", "person_seating"]
      ,
      "required": true
      },
      {
        "id": "tv_facing_seat",
        "relation": "faces",
        "participant_roles": ["television", "person_seating"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshments",
        "operation": "place_on",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "move_to",
        "participant_roles": ["entertainment_control", "surface"],
        "operation_count": 1
      }
    ]
  },
